CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "Role" AS ENUM ('OWNER', 'MANAGER', 'VIEWER');
CREATE TYPE "RiskLevel" AS ENUM ('LOW', 'MODERATE', 'HIGH', 'CRITICAL', 'UNKNOWN');
CREATE TYPE "CommandStatus" AS ENUM ('QUEUED', 'RECEIVED', 'ACCEPTED', 'APPLIED', 'REJECTED', 'FAILED', 'TIMED_OUT');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'VIEWER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Organization" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Membership" ("userId" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "role" "Role" NOT NULL, PRIMARY KEY ("userId", "organizationId"));
CREATE TABLE "Site" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, UNIQUE ("organizationId", "name"));
CREATE TABLE "Plot" ("id" TEXT PRIMARY KEY, "siteId" TEXT NOT NULL, "name" TEXT NOT NULL, "crop" TEXT, UNIQUE ("siteId", "name"));
CREATE TABLE "Device" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "plotId" TEXT, "displayName" TEXT, "hardwareModel" TEXT, "firmwareVersion" TEXT, "lastSeenAt" TIMESTAMP(3), "lastConfigurationRevision" INTEGER);
CREATE TABLE "RawMessage" ("id" TEXT PRIMARY KEY, "messageId" TEXT NOT NULL UNIQUE, "deviceId" TEXT NOT NULL, "topic" TEXT NOT NULL, "messageType" TEXT NOT NULL, "payload" JSONB NOT NULL, "ingestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "deviceTime" TIMESTAMP(3));
CREATE TABLE "Telemetry" ("id" TEXT PRIMARY KEY, "messageId" TEXT NOT NULL UNIQUE, "deviceId" TEXT NOT NULL, "sampledAt" TIMESTAMP(3), "ingestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "temperatureC" DOUBLE PRECISION, "humidityPct" DOUBLE PRECISION, "relativeMoisturePct" DOUBLE PRECISION, "batteryV" DOUBLE PRECISION, "solarV" DOUBLE PRECISION, "valid" JSONB NOT NULL, "raw" JSONB NOT NULL);
CREATE TABLE "DeviceEvent" ("id" TEXT PRIMARY KEY, "messageId" TEXT NOT NULL UNIQUE, "deviceId" TEXT NOT NULL, "code" TEXT NOT NULL, "payload" JSONB NOT NULL, "occurredAt" TIMESTAMP(3), "ingestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "DeviceSnapshot" ("id" TEXT PRIMARY KEY, "deviceId" TEXT NOT NULL, "kind" TEXT NOT NULL, "payload" JSONB NOT NULL, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("deviceId", "kind"));
CREATE TABLE "Command" ("id" TEXT PRIMARY KEY, "requestId" TEXT NOT NULL UNIQUE, "deviceId" TEXT NOT NULL, "command" TEXT NOT NULL, "args" JSONB NOT NULL, "expectedRevision" INTEGER, "expiresAt" TIMESTAMP(3) NOT NULL, "status" "CommandStatus" NOT NULL DEFAULT 'QUEUED', "response" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "createdById" TEXT);
CREATE TABLE "RiskAssessment" ("id" TEXT PRIMARY KEY, "deviceId" TEXT NOT NULL, "telemetryId" TEXT, "level" "RiskLevel" NOT NULL, "ruleVersion" TEXT NOT NULL, "factors" JSONB NOT NULL, "explanation" TEXT NOT NULL, "calculatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AlertRule" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "thresholds" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "userId" TEXT, "action" TEXT NOT NULL, "targetType" TEXT NOT NULL, "targetId" TEXT NOT NULL, "detail" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "NotificationPreference" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "channel" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "destination" TEXT, UNIQUE ("userId", "channel"));
CREATE INDEX "Telemetry_deviceId_ingestedAt_idx" ON "Telemetry"("deviceId", "ingestedAt");
CREATE INDEX "DeviceEvent_deviceId_ingestedAt_idx" ON "DeviceEvent"("deviceId", "ingestedAt");
CREATE INDEX "Command_deviceId_createdAt_idx" ON "Command"("deviceId", "createdAt");
CREATE INDEX "RiskAssessment_deviceId_calculatedAt_idx" ON "RiskAssessment"("deviceId", "calculatedAt");
ALTER TABLE "Membership" ADD FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE;
ALTER TABLE "Membership" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE;
ALTER TABLE "Site" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE;
ALTER TABLE "Plot" ADD FOREIGN KEY ("siteId") REFERENCES "Site"("id") ON DELETE CASCADE;
ALTER TABLE "Device" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE;
ALTER TABLE "Device" ADD FOREIGN KEY ("plotId") REFERENCES "Plot"("id") ON DELETE SET NULL;
ALTER TABLE "RawMessage" ADD FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE;
ALTER TABLE "Telemetry" ADD FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE;
ALTER TABLE "DeviceEvent" ADD FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE;
ALTER TABLE "DeviceSnapshot" ADD FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE;
ALTER TABLE "Command" ADD FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE;
ALTER TABLE "RiskAssessment" ADD FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE;
ALTER TABLE "AlertRule" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE;
ALTER TABLE "AuditLog" ADD FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL;
